by={r['id']:r for r in rows};assert len(by)==len(rows)==len(scenarios)==64
for s in scenarios:
 r=by[s['id']];r['title']=s['title']
 for e in r['evidence']:
  if not (root/e).exists():print('MISSING EVIDENCE',s['id'],e)
ordered=[by[s['id']] for s in scenarios];(root/'scenario-verification.json').write_text(json.dumps(ordered,ensure_ascii=False,indent=2),encoding='utf-8')
lines=['# Итоговая ведомость 64 сценариев','', 'Дата: 9 ноября 2026 года. Сборка 1.1.0. Исходная сверка в scenarios.json сохраняется как история; эта ведомость описывает нынешний результат и ограничения. «Проверено технически» не означает клиническую или аппаратную приёмку.','', '| Код | Сценарий | Результат | Проверка и ограничения |','| --- | --- | --- | --- |']
for r in ordered:lines.append('| '+r['id']+' | '+r['title']+' | '+r['status']+' | '+r['result']+' '+', '.join(f'[{Path(e).name}]({e})' for e in r['evidence'])+' |')
(root/'SCENARIO-VERIFICATION.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Scenarios reviewed:',len(ordered))
